 func send<T:Decodable>(_ endpoint:APIEndpoint,method:HTTPMethod = .get,body:Encodable?=nil,as:T.Type=T.self)async throws->T{let bodyData=try body.map{try JSONEncoder().encode(AnyEncodable($0))};let data=try await sendValidatedRaw(endpoint,method:method,body:bodyData);if T.self==Empty.self{return Empty() as! T};return try JSONDecoder.health.decode(OCSResponse<T>.self,from:data).ocs.data}
