 func removeAppPassword()async throws{var u=server.url;u.append(path:"ocs/v2.php/core/apppassword");var r=URLRequest(url:u);r.httpMethod="DELETE";r.setValue(authorization,forHTTPHeaderField:"Authorization");r.setValue("true",forHTTPHeaderField:"OCS-APIRequest");r.setValue("application/json",forHTTPHeaderField:"Accept");let(data,response)=try await session.data(for:r);guard (response as? HTTPURLResponse)?.statusCode==200 else{throw HealthCoreError.invalidResponse};let envelope=try JSONDecoder.health.decode(OCSMetadataResponse.self,from:data);try envelope.ocs.meta.validate()}
 private func checkRemoteWipe()async throws->Bool{struct Wipe:Decodable{let wipe:Bool};var u=server.url;u.append(path:"index.php/core/wipe/check");var r=URLRequest(url:u);r.httpMethod="POST";r.setValue("application/x-www-form-urlencoded",forHTTPHeaderField:"Content-Type");r.httpBody=Data(FormEncoding.field("token",value:account.appPassword).utf8);let(d,response)=try await session.data(for:r);guard (response as? HTTPURLResponse)?.statusCode==200,let result=try? JSONDecoder().decode(Wipe.self,from:d) else{return false};return result.wipe}
