@MainActor enum NextcloudLoginFlow {
 static func start(server:ServerConfiguration)async throws->(LoginFlowStart,URLSession){let c=URLSessionConfiguration.ephemeral;let s=URLSession(configuration:c);let u=server.url.appending(path:"index.php/login/v2");var r=URLRequest(url:u);r.httpMethod="POST";let(d,response)=try await s.data(for:r);guard (response as? HTTPURLResponse)?.statusCode==200 else{throw HealthCoreError.invalidResponse};let start=try JSONDecoder().decode(LoginFlowStart.self,from:d);guard let login=URL(string:start.login)else{throw HealthCoreError.invalidResponse};UIApplication.shared.open(login);return(start,s)}
 static func poll(_ start:LoginFlowStart,session:URLSession,timeout:Duration = .seconds(300))async throws->LoginFlowResult{let clock=ContinuousClock();let deadline=clock.now.advanced(by:timeout);guard let u=URL(string:start.poll.endpoint),u.scheme=="https" else{throw HealthCoreError.insecureServer};while clock.now<deadline{var r=URLRequest(url:u);r.httpMethod="POST";r.setValue("application/x-www-form-urlencoded",forHTTPHeaderField:"Content-Type");r.httpBody=Data(FormEncoding.field("token",value:start.poll.token).utf8);let(d,res)=try await session.data(for:r);let status=(res as? HTTPURLResponse)?.statusCode;if status==200{return try JSONDecoder().decode(LoginFlowResult.self,from:d)};guard status==404 else{throw HealthCoreError.invalidResponse};try await Task.sleep(for:.seconds(1))};throw URLError(.timedOut)} }
